"""Compliance: bookkeeping, audit and review, HR and payroll."""

BOOKS = [('Bank statements', 'For all business accounts.'), ('Sales and purchase invoices', 'Or access to your billing software.'), ('Expense bills', 'Rent, salaries, utilities and other costs.'), ('GST and TDS returns', 'If already filed.'), ('Accounting software access', 'Tally, Zoho Books, QuickBooks or similar.')]
