AUDIT_STEPS = [('Plan', 'We understand your business and agree scope and timeline.'),
               ('Fieldwork', 'Records are examined, remotely or on site.'),
               ('Discuss findings', 'We walk you through observations before finalising.'),
               ('Report', 'You receive the signed report and action points.')]
MONTHLY = [('Onboard', 'We understand your business and set up a document flow.'),
           ('Record', 'Transactions are recorded and reconciled every month.'),
           ('Review', 'You receive monthly reports and we discuss them.'),
           ('Comply', 'Returns are filed on time from clean books.')]
PAYROLL_DOCS = [('Employee master data', 'Name, PAN, Aadhaar, bank account, salary structure and joining date.'), ('Attendance and leave', 'For each month.'), ('Investment declarations', 'For TDS on salary.'), ('Registrations', 'PF, ESI, professional tax and TAN, if already obtained.')]

